import { http, HttpResponse } from "msw";
import { faker } from "@faker-js/faker";
import route from "../../route";

const ROUTE = `${route.VERSION}/${route.USER_MANAGEMENT}/auth/`

const signInAuth = [
    http.post(ROUTE + 'sign-in', async ({ }) => {
        return HttpResponse.json({ accessToken: 'fake-token' });
    }),
];

const signUpAuth = [
    http.post(ROUTE + 'sign-up', async ({ }) => {
        return HttpResponse.json({ accessToken: 'fake-token' });
    }),
];

const signOutAuth = [
    http.get(ROUTE + 'sign-out', async ({ }) => {
        return HttpResponse.json();
    }),
];

const requestResetPasswordAuth = [
    http.post(ROUTE + 'request-reset-password', async ({ }) => {
        return HttpResponse.json();
    }),
];

const resetPasswordAuth = [
    http.patch(ROUTE + 'reset-password', async ({ }) => {
        return HttpResponse.json();
    }),
];

export default [
    ...signInAuth,
    ...signUpAuth,
    ...signOutAuth,
    ...requestResetPasswordAuth,
    ...resetPasswordAuth,
];